-- Carga autocontenida de la red de resiliencia (fibra, sismo, modelo de falla).
-- Requiere PostGIS y pgRouting disponibles. Ejecutar sobre una base de datos vacia.

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgrouting;

-- Tabla edges
DROP TABLE IF EXISTS edges CASCADE;
CREATE TABLE edges (
    "id" integer NOT NULL,
    "tipo" text,
    "sintetico" boolean DEFAULT false,
    "operativo" boolean DEFAULT true,
    "id_origen" text,
    "geom" geometry(LineString,32719),
    "largo_m" double precision,
    "source" integer,
    "target" integer,
    "p_falla" double precision DEFAULT 0 NOT NULL,
    "dist_ruptura_km" double precision,
    "pga_g" double precision,
    "pgv_cms" double precision,
    "rr_km" double precision,
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS "edges_geom_gist" ON edges USING GIST ("geom");

-- Tabla edges_vertices_pgr
DROP TABLE IF EXISTS edges_vertices_pgr CASCADE;
CREATE TABLE edges_vertices_pgr (
    "id" bigint NOT NULL,
    "cnt" integer,
    "chk" integer,
    "ein" integer,
    "eout" integer,
    "the_geom" geometry(Point,32719),
    "grado" integer,
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS "edges_vertices_pgr_the_geom_gist" ON edges_vertices_pgr USING GIST ("the_geom");

-- Tabla nodos_clave
DROP TABLE IF EXISTS nodos_clave CASCADE;
CREATE TABLE nodos_clave (
    "cod" text NOT NULL,
    "nombre" text,
    "rol" text,
    "tipo" text,
    "fuente" text,
    "geom" geometry(Point,4326),
    "vertex_id" integer,
    "dist_acceso_m" double precision,
    "componente" bigint,
    PRIMARY KEY (cod)
);

CREATE INDEX IF NOT EXISTS "nodos_clave_geom_gist" ON nodos_clave USING GIST ("geom");

-- Tabla sismo
DROP TABLE IF EXISTS sismo CASCADE;
CREATE TABLE sismo (
    "evento_id" text NOT NULL,
    "lugar" text,
    "mag" double precision,
    "fecha_utc" timestamp with time zone,
    "profundidad_km" double precision,
    "strike_deg" double precision,
    "fuente_url" text,
    "geom" geometry(Point,4326),
    PRIMARY KEY (evento_id)
);

CREATE INDEX IF NOT EXISTS "sismo_geom_gist" ON sismo USING GIST ("geom");

-- Tabla ruptura
DROP TABLE IF EXISTS ruptura CASCADE;
CREATE TABLE ruptura (
    "id" integer NOT NULL,
    "largo_km" double precision,
    "geom" geometry(LineString,32719),
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS "ruptura_geom_gist" ON ruptura USING GIST ("geom");

-- Tabla modelo_param
DROP TABLE IF EXISTS modelo_param CASCADE;
CREATE TABLE modelo_param (
    "clave" text NOT NULL,
    "valor" double precision,
    "descripcion" text,
    "fuente" text,
    PRIMARY KEY (clave)
);


-- Tabla componentes
DROP TABLE IF EXISTS componentes CASCADE;
CREATE TABLE componentes (
    "vertex_id" integer NOT NULL,
    "componente" bigint,
    PRIMARY KEY (vertex_id)
);


