-- Funciones del modelo de falla
CREATE OR REPLACE FUNCTION public.param_valor(clave text)
 RETURNS double precision
 LANGUAGE sql
 STABLE
AS $function$
    SELECT valor FROM modelo_param WHERE modelo_param.clave = param_valor.clave
$function$;

CREATE OR REPLACE FUNCTION public.pga_youngs(m double precision, r_km double precision, h_km double precision)
 RETURNS double precision
 LANGUAGE sql
 STABLE
AS $function$
    SELECT exp(
        param_valor('c_youngs_a')
        + param_valor('c_youngs_b') * m
        + param_valor('c_youngs_c3') * ln(r_km + param_valor('c_youngs_d') * exp(param_valor('c_youngs_e') * m))
        + param_valor('c_youngs_h') * h_km
    )
$function$;

CREATE OR REPLACE FUNCTION public.p_falla_enlace(pgv double precision, largo_km double precision, k double precision)
 RETURNS double precision
 LANGUAGE sql
 STABLE
AS $function$
    SELECT 1 - exp(-k * param_valor('rr_coef') * power(pgv, param_valor('rr_exp')) * largo_km)
$function$;

-- Vista
CREATE OR REPLACE VIEW v_probabilidad_falla AS
 SELECT id,
    tipo,
    sintetico,
    largo_m / 1000.0::double precision AS largo_km,
    dist_ruptura_km,
    pga_g,
    pgv_cms,
    rr_km,
    p_falla
   FROM edges
  ORDER BY p_falla DESC;

